          <line x1="28" y1="96" x2="28" y2="12" stroke="#94a3b8" stroke-width="1.5"/>
          <path id="miniPath" fill="none" stroke="#2563eb" stroke-width="2.5" stroke-linecap="round"/>
          <line id="miniMinGuide" stroke="#94a3b8" stroke-width="1" stroke-dasharray="3 3"/>
