<script>
(function () {
  const ionTypes = {
    ba:  { label: 'Ba²⁺',  short: 'Ba',  color: '#3b82f6', r: 10 },
    oh:  { label: 'OH⁻',   short: 'OH',  color: '#ef4444', r: 7 },
    h:   { label: 'H⁺',    short: 'H',   color: '#f59e0b', r: 6 },
    so4: { label: 'SO₄²⁻', short: 'SO₄', color: '#10b981', r: 9 },
    k:   { label: 'K⁺',    short: 'K',   color: '#8b5cf6', r: 7 },
    na:  { label: 'Na⁺',   short: 'Na',  color: '#eab308', r: 7 },
    mg:  { label: 'Mg²⁺',  short: 'Mg',  color: '#14b8a6', r: 9 }
  };

  const experimentSpecs = {
    h2so4: { base: 'Ba(OH)₂ 溶液', titrant: '稀 H₂SO₄', titrantKey: 'h2so4' },
    naoh:  { base: 'NaOH 溶液', titrant: '稀 H₂SO₄', titrantKey: 'h2so4' },
    khso4: { base: 'Ba(OH)₂ 溶液', titrant: '稀 KHSO₄', titrantKey: 'khso4' },
    mgso4: { base: 'Ba(OH)₂ 溶液', titrant: '稀 MgSO₄', titrantKey: 'mgso4' }
  };

  const titrantColors = {
    h2so4: '#60a5fa',
    khso4: '#a78bfa',
    mgso4: '#2dd4bf'
  };

  const state = { exp: 'h2so4', t: 0, playing: false, rafId: null };
  let stepIndex = 1;
  let highlightPrecip = false;

  function mulberry32(a) {
    return function () {
      var t = a += 0x6D2B79F5;
      t = Math.imul(t ^ t >>> 15, t | 1);
      t ^= t + Math.imul(t ^ t >>> 7, t | 61);
      return ((t ^ t >>> 14) >>> 0) / 4294967296;
    };
  }

  const rand = mulberry32(20240501);
  const slots = [];
  for (let row = 0; row < 6; row++) {
    for (let col = 0; col < 8; col++) {
      slots.push({
        x: 108 + col * 30 + (rand() - 0.5) * 8,
        y: 95 + row * 26 + (rand() - 0.5) * 6
      });
    }
  }

  const groupStart = { ba: 0, mg: 0, oh: 8, h: 8, so4: 24, na: 32, k: 32 };

  function conductivity(exp, t) {
    t = Math.max(0, Math.min(2, t));
    if (exp === 'h2so4') {
      if (t <= 1) return (1 - t) / (1 + 0.5 * t);
      return (t - 1) / (1 + 0.5 * t);
    }
    if (exp === 'mgso4') {
      if (t <= 1) return (1 - t) / (1 + 0.5 * t);
      return 0.9 * (t - 1) / (1 + 0.5 * t);
    }
    if (exp === 'naoh') {
      if (t <= 1) return (1 - 0.2 * t) / (1 + 0.1 * t);
      return (0.8 + 0.3 * (t - 1)) / (1 + 0.1 * t);
    }
    if (exp === 'khso4') {
      if (t <= 1) return (1 - 0.5 * t) / (1 + 0.25 * t);
      return (0.5 + 0.5 * (t - 1)) / (1 + 0.25 * t);
    }
    return 0;
  }

  function getState(exp, t) {
    let counts = { ba: 0, oh: 0, h: 0, so4: 0, k: 0, na: 0, mg: 0 };
    let precip = { baso4: 0, mgoh2: 0 };
    t = Math.max(0, Math.min(2, t));

    if (exp === 'h2so4') {
      if (t <= 1) {
        counts.ba = Math.round(8 * (1 - t));
        counts.oh = Math.round(16 * (1 - t));
        precip.baso4 = Math.round(8 * t);
      } else {
        precip.baso4 = 8;
        counts.h = Math.round(16 * (t - 1));
        counts.so4 = Math.round(8 * (t - 1));
      }
    } else if (exp === 'naoh') {
      counts.na = 8;
      if (t <= 1) {
        counts.oh = Math.max(0, Math.round(8 * (1 - t)));
        counts.so4 = Math.round(4 * t);
      } else {
        counts.so4 = Math.round(4 * t);
        counts.h = Math.round(8 * (t - 1));
      }
    } else if (exp === 'khso4') {
      const n = 8 * t;
      counts.k = Math.round(n);
      if (n <= 8) {
        counts.ba = Math.round(8 - n);
        counts.oh = Math.round(16 - n);
        precip.baso4 = Math.round(n);
      } else {
        counts.oh = Math.max(0, Math.round(16 - n));
        counts.so4 = Math.round(n - 8);
        precip.baso4 = 8;
      }
    } else if (exp === 'mgso4') {
      const n = 8 * t;
      if (t <= 1) {
        counts.ba = Math.round(8 * (1 - t));
        counts.oh = Math.round(16 * (1 - t));
        precip.baso4 = Math.round(8 * t);
        precip.mgoh2 = Math.round(8 * t);
      } else {
        precip.baso4 = 8;
        precip.mgoh2 = 8;
        counts.mg = Math.round(8 * (t - 1));
        counts.so4 = Math.round(8 * (t - 1));
      }
    }
    return { counts, precip };
  }

  const chartGeom = { left: 70, right: 610, bottom: 280, top: 40, yScale: 220 };
  function xOf(t) { return chartGeom.left + (t / 2) * (chartGeom.right - chartGeom.left); }
  function yOf(v) { return chartGeom.bottom - v * chartGeom.yScale; }

  function buildPath(exp) {
    let d = '';
    for (let i = 0; i <= 100; i++) {
      const t = (i / 100) * 2;
      const v = conductivity(exp, t);
      d += (i === 0 ? 'M' : 'L') + xOf(t).toFixed(1) + ',' + yOf(v).toFixed(1) + ' ';
    }
    return d;
  }

  function drawCurve() {
    const exp = state.exp, t = state.t;
    document.getElementById('currentPath').setAttribute('d', buildPath(exp));
    document.getElementById('referencePath').setAttribute('d', buildPath('h2so4'));

    const v = conductivity(exp, t);
    const x = xOf(t), y = yOf(v);
    const dot = document.getElementById('currentDot');
    dot.setAttribute('cx', x);
    dot.setAttribute('cy', y);

    const line = document.getElementById('currentLine');
    line.setAttribute('x1', x);
    line.setAttribute('x2', x);
    line.setAttribute('y1', y);
    line.setAttribute('y2', chartGeom.bottom);

    const tA = 0.08, tB = 1, tC = 1.8;
    const vA = conductivity('h2so4', tA), vC = conductivity('h2so4', tC);
    document.getElementById('labelA').setAttribute('x', xOf(tA) + 8);
    document.getElementById('labelA').setAttribute('y', yOf(vA) - 8);
    document.getElementById('labelB').setAttribute('x', xOf(tB) - 16);
    document.getElementById('labelB').setAttribute('y', yOf(0) - 14);
    document.getElementById('labelC').setAttribute('x', xOf(tC) + 8);
    document.getElementById('labelC').setAttribute('y', yOf(vC) - 8);

    const minV = conductivity(exp, 1);
    const minX = xOf(1), minY = yOf(minV);
    const minLabel = document.getElementById('minLabel');
    minLabel.textContent = '最低点 ≈ ' + minV.toFixed(2);
    const labelX = minX + 18;
    const labelY = minV < 0.15 ? 238 : Math.min(270, minY + 28);
    minLabel.setAttribute('x', labelX);
    minLabel.setAttribute('y', labelY);
    minLabel.setAttribute('text-anchor', 'start');
    minLabel.setAttribute('fill', minV < 0.05 ? '#16a34a' : '#475569');
    const guide = document.getElementById('minGuide');
    guide.setAttribute('x1', minX);
    guide.setAttribute('y1', minY);
    guide.setAttribute('x2', labelX - 2);
    guide.setAttribute('y2', labelY - 4);
    guide.setAttribute('opacity', '1');
    guide.setAttribute('stroke', minV < 0.05 ? '#16a34a' : '#94a3b8');
  }

  function renderBeaker(stateData) {
    const layer = document.getElementById('particleLayer');
    const { counts, precip } = stateData;
    let html = '';

    const order = ['ba', 'mg', 'oh', 'h', 'so4', 'na', 'k'];
    for (const key of order) {
      const n = counts[key];
      for (let i = 0; i < n; i++) {
        const pos = slots[groupStart[key] + i];
        if (!pos) continue;
        const ion = ionTypes[key];
        const fontSize = ion.r >= 9 ? 7 : 6;
        html += '<g class="ion-particle" transform="translate(' + pos.x.toFixed(1) + ',' + pos.y.toFixed(1) + ')">'
          + '<circle r="' + ion.r + '" fill="' + ion.color + '" stroke="#ffffff" stroke-width="1.5"/>'
          + '<text y="' + (ion.r >= 9 ? 2.5 : 2) + '" text-anchor="middle" font-size="' + fontSize + '" fill="#ffffff" font-weight="700" style="pointer-events:none">' + ion.short + '</text>'
          + '</g>';
      }
    }

    const precipClass = highlightPrecip ? 'precip-particle highlight' : 'precip-particle';
    for (let i = 0; i < precip.baso4; i++) {
      const x = 114 + i * 24;
      html += '<rect class="' + precipClass + '" x="' + (x - 5) + '" y="221" width="10" height="10" rx="2" fill="#94a3b8" stroke="#ffffff" stroke-width="1"/>';
    }
    for (let i = 0; i < precip.mgoh2; i++) {
      const x = 114 + i * 24;
      html += '<circle class="' + precipClass + '" cx="' + x + '" cy="242" r="5" fill="#d1d5db" stroke="#ffffff" stroke-width="1"/>';
    }

    layer.innerHTML = html;
  }

  function renderCounts(stateData) {
    const { counts, precip } = stateData;
    const rows = [
      ['ba', 'Ba²⁺', counts.ba],
      ['oh', 'OH⁻', counts.oh],
      ['h', 'H⁺', counts.h],
      ['so4', 'SO₄²⁻', counts.so4],
      ['k', 'K⁺', counts.k],
      ['na', 'Na⁺', counts.na],
      ['mg', 'Mg²⁺', counts.mg]
    ];

    let html = rows.map(function (row) {
      const key = row[0], label = row[1], n = row[2];
      const ion = ionTypes[key];
      const residual = state.highlightResidual === key && n > 0;
      return '<div class="ion-row ' + (n === 0 ? 'zero' : '') + (residual ? ' residual-highlight' : '') + '">'
        + '<span class="dot" style="background:' + ion.color + '"></span>'
        + '<span class="ion-label">' + label + '</span>'
        + '<span class="ion-num">× ' + n + (residual ? ' <em>残留</em>' : '') + '</span>'
        + '</div>';
    }).join('');

    if (precip.baso4 > 0) {
      html += '<div class="ion-row precip-row"><span class="dot square" style="background:#94a3b8"></span><span class="ion-label">BaSO₄↓</span><span class="ion-num">× ' + precip.baso4 + '</span></div>';
    }
    if (precip.mgoh2 > 0) {
      html += '<div class="ion-row precip-row"><span class="dot circle" style="background:#d1d5db"></span><span class="ion-label">Mg(OH)₂↓</span><span class="ion-num">× ' + precip.mgoh2 + '</span></div>';
    }

    document.getElementById('ionCounts').innerHTML = html;
  }

  function getStatusText(exp, t) {
    if (exp === 'h2so4') {
      if (t < 0.05) return '初始：Ba²⁺、OH⁻ 多，导电强';
      if (t < 0.95) return 'AB 段：离子被消耗，导电能力下降';
      if (t <= 1.05) return 'B 点：离子浓度接近 0，导电能力最低';
      return 'BC 段：硫酸过量，H⁺、SO₄²⁻ 增多，导电能力回升';
    }
    if (exp === 'naoh') {
      if (t < 0.95) return 'Na⁺ 始终留在溶液中，导电能力不会降到 0';
      return '过量硫酸增加离子，但最低点仍不为 0';
    }
    if (exp === 'khso4') {
      if (t < 0.95) return 'Ba²⁺ 被沉淀，但 K⁺ 留在溶液中';
      return 'OH⁻ 继续被中和，K⁺、SO₄²⁻ 增多；最低点不为 0';
    }
    if (exp === 'mgso4') {
      if (t < 0.95) return 'Ba²⁺、OH⁻ 被两种沉淀消耗，离子减少';
      if (t <= 1.05) return '恰好完全反应：离子浓度接近 0，导电能力最低';
      return '过量 MgSO₄ 提供 Mg²⁺、SO₄²⁻，导电能力回升';
    }
    return '';
  }

  function drawMini(exp) {
    const svg = document.getElementById('miniChart');
    if (!svg) return;
    const L = 28, R = 344, T = 14, B = 96;
    const yScale = (B - T) / 1.05;
    const mx = function (t) { return L + (t / 2) * (R - L); };
    const my = function (v) { return B - v * yScale; };
    let d = '';
    for (let i = 0; i <= 80; i++) {
      const t = (i / 80) * 2;
      const v = conductivity(exp, t);
      d += (i === 0 ? 'M' : 'L') + mx(t).toFixed(1) + ',' + my(v).toFixed(1) + ' ';
    }
    document.getElementById('miniPath').setAttribute('d', d);
    const minV = conductivity(exp, 1);
    const bx = mx(1), by = my(minV);
    const dot = document.getElementById('miniMinDot');
    dot.setAttribute('cx', bx);
    dot.setAttribute('cy', by);
    const label = document.getElementById('miniMinLabel');
    const labelX = bx + 10;
    const labelY = minV < 0.15 ? 58 : Math.max(18, by - 10);
    label.textContent = '最低点 ≈ ' + minV.toFixed(2);
    label.setAttribute('x', labelX);
    label.setAttribute('y', labelY);
    label.setAttribute('fill', minV < 0.05 ? '#16a34a' : '#475569');
    const guide = document.getElementById('miniMinGuide');
    guide.setAttribute('x1', bx);
    guide.setAttribute('y1', by);
    guide.setAttribute('x2', labelX - 2);
    guide.setAttribute('y2', labelY + 3);
    guide.setAttribute('stroke', minV < 0.05 ? '#16a34a' : '#94a3b8');
    const spec = experimentSpecs[exp];
    document.getElementById('miniExpLabel').textContent = '底液：' + spec.base + ' · 滴加：' + spec.titrant;
    document.getElementById('miniMinValue').textContent = minV.toFixed(2);
    document.getElementById('miniResidual').textContent = exp === 'naoh' ? '残留 Na⁺' : (exp === 'khso4' ? '残留 K⁺' : '残留离子少');
  }

  function update() {
    const exp = state.exp, t = state.t;
    const dose = document.getElementById('dose');
    dose.value = t;
    document.getElementById('doseValue').textContent = t.toFixed(2);

    document.querySelectorAll('.exp-btn').forEach(function (btn) {
      btn.classList.toggle('active', btn.dataset.exp === exp);
    });

    if (exp === 'naoh') state.highlightResidual = 'na';
    else if (exp === 'khso4') state.highlightResidual = 'k';
    else state.highlightResidual = null;

    const spec = experimentSpecs[exp];
    document.getElementById('chartExpLabel').textContent = '底液：' + spec.base + ' · 滴加：' + spec.titrant;
    document.getElementById('beakerBaseLabel').textContent = '底液：' + spec.base;
    document.getElementById('beakerTitrantLabel').textContent = '滴加：' + spec.titrant;
    document.getElementById('droplet').setAttribute('fill', titrantColors[spec.titrantKey]);
    document.getElementById('droplet').style.display = t < 1.99 ? '' : 'none';

    drawCurve();
    drawMini(exp);

    const stateData = getState(exp, t);
    renderBeaker(stateData);
    renderCounts(stateData);

    const v = conductivity(exp, t);
    document.getElementById('conductValue').textContent = v.toFixed(2);
    document.getElementById('conductBar').style.width = Math.min(100, Math.max(0, v * 100)) + '%';
    document.getElementById('statusLine').textContent = getStatusText(exp, t);
  }

  function stopPlay() {
    state.playing = false;
    if (state.rafId) cancelAnimationFrame(state.rafId);
    state.rafId = null;
    document.getElementById('playBtn').textContent = '播放';
  }

  function togglePlay() {
    if (state.playing) {
      stopPlay();
      return;
    }
    state.playing = true;
    document.getElementById('playBtn').textContent = '暂停';
    if (state.t >= 1.99) state.t = 0;

    let last = performance.now();
    function frame(now) {
      if (!state.playing) return;
      const dt = Math.min(60, now - last);
      last = now;
      state.t = Math.min(2, state.t + dt * 0.00035);
      update();
      if (state.t >= 1.999) {
        stopPlay();
      } else {
        state.rafId = requestAnimationFrame(frame);
      }
    }
    state.rafId = requestAnimationFrame(frame);
  }

  const stepData = {
    1: { title: '题设理解', desc: 'Ba(OH)₂ 溶液中有大量 Ba²⁺ 和 OH⁻，所以初始导电能力强。', exp: 'h2so4', t: 0 },
    2: { title: '建立表示', desc: '横轴看滴加量，纵轴看相对导电能力；曲线与烧杯中的离子数联动。', exp: 'h2so4', t: 0.4 },
    3: { title: 'AB 段：离子被消耗', desc: 'Ba²⁺ + SO₄²⁻ → BaSO₄↓；H⁺ + OH⁻ → H₂O。自由离子减少，导电能力下降。', exp: 'h2so4', t: 0.6 },
    4: { title: 'B 点：恰好完全反应', desc: '溶液中离子浓度接近 0，导电能力最低。', exp: 'h2so4', t: 1 },
    5: { title: 'BC 段：硫酸过量', desc: '过量的 H₂SO₄ 电离出 H⁺ 和 SO₄²⁻，导电能力回升。', exp: 'h2so4', t: 1.5 },
    6: { title: '对比选项', desc: '换用不同试剂，观察曲线最低点能否接近 0。点击下方选项验证。', exp: 'h2so4', t: 1 }
  };

  function setStepActive(n) {
    document.querySelectorAll('.step-btn').forEach(function (btn) {
      btn.classList.toggle('active', parseInt(btn.dataset.step, 10) === n);
    });
  }

  function setStep(n) {
    stopPlay();
    stepIndex = n;
    setStepActive(n);
    const d = stepData[n];
    state.exp = d.exp;
    state.t = d.t;
    document.getElementById('stepTitle').textContent = d.title;
    document.getElementById('stepDesc').textContent = d.desc;
    update();
  }

  function switchExperiment(exp) {
    stopPlay();
    state.exp = exp;
    state.t = 1;
    state.highlightResidual = exp === 'naoh' ? 'na' : (exp === 'khso4' ? 'k' : null);
    stepIndex = 6;
    setStepActive(6);
    const spec = experimentSpecs[exp];
    const minV = conductivity(exp, 1);
    document.getElementById('stepTitle').textContent = '对比选项';
    document.getElementById('stepDesc').textContent = '当前：底液 ' + spec.base + '，滴加 ' + spec.titrant + '；最低导电能力 ≈ ' + minV.toFixed(2) + '。' + (state.highlightResidual ? '图中高亮的是残留在溶液中的离子。' : '恰好反应时离子浓度接近 0。');
    update();
  }

  const steps = [
    { n: 1, short: '题设' },
    { n: 2, short: '表示' },
    { n: 3, short: 'AB段' },
    { n: 4, short: 'B点' },
    { n: 5, short: 'BC段' },
    { n: 6, short: '对比' }
  ];

  function initStepNav() {
    const nav = document.getElementById('stepNav');
    nav.innerHTML = steps.map(function (s) {
      return '<button type="button" class="step-btn" data-step="' + s.n + '"><b>' + s.n + '</b>' + s.short + '</button>';
    }).join('');
    nav.querySelectorAll('.step-btn').forEach(function (btn) {
      btn.addEventListener('click', function () {
        setStep(parseInt(btn.dataset.step, 10));
      });
    });
  }

  function handleOption(opt) {
    const btn = document.querySelector('.option[data-opt="' + opt + '"]');
    const feedback = document.getElementById('optionFeedback');
    const conclusion = document.getElementById('finalConclusion');

    if (opt === 'A') {
      stopPlay();
      state.exp = 'h2so4';
      state.t = 1;
      stepIndex = 4;
      setStepActive(4);
      document.getElementById('stepTitle').textContent = 'B 点：恰好完全反应';
      document.getElementById('stepDesc').textContent = '导电弱是因为溶液中自由离子少。BaSO₄ 难溶，但它是强电解质。';
      update();
      btn.classList.remove('correct');
      btn.classList.add('wrong');
      feedback.innerHTML = '<b>A 不正确：</b>BaSO₄ 难溶，但溶解的少量仍完全电离，是强电解质。导电能力弱是因为溶液中自由离子少。';
      feedback.className = 'feedback wrong';
      highlightPrecip = true;
      renderBeaker(getState(state.exp, state.t));
      setTimeout(function () {
        highlightPrecip = false;
        renderBeaker(getState(state.exp, state.t));
      }, 1600);
    } else if (opt === 'B') {
      switchExperiment('naoh');
      btn.classList.remove('correct');
      btn.classList.add('wrong');
      feedback.innerHTML = '<b>B 不正确：</b>Na⁺ 和 SO₄²⁻ 始终留在溶液中，最低点仍约为 0.73，不能降到接近 0。';
      feedback.className = 'feedback wrong';
    } else if (opt === 'C') {
      switchExperiment('khso4');
      btn.classList.remove('correct');
      btn.classList.add('wrong');
      feedback.innerHTML = '<b>C 不正确：</b>K⁺ 留在溶液中，最低点约为 0.40，不能降到接近 0。';
      feedback.className = 'feedback wrong';
    } else if (opt === 'D') {
      switchExperiment('mgso4');
      btn.classList.remove('wrong');
      btn.classList.add('correct');
      feedback.innerHTML = '<b>D 正确：</b>MgSO₄ 与 Ba(OH)₂ 生成 BaSO₄ 和 Mg(OH)₂ 两种沉淀；恰好反应时离子浓度接近 0，过量后离子增多，曲线先降后升。';
      feedback.className = 'feedback correct';
      conclusion.style.display = 'block';
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    initStepNav();
    document.getElementById('playBtn').addEventListener('click', togglePlay);
    document.getElementById('resetBtn').addEventListener('click', function () {
      stopPlay();
      state.t = 0;
      update();
    });
    document.getElementById('dose').addEventListener('input', function (e) {
      stopPlay();
      state.t = parseFloat(e.target.value);
      update();
    });
    document.querySelectorAll('.exp-btn').forEach(function (btn) {
      btn.addEventListener('click', function () {
        switchExperiment(btn.dataset.exp);
      });
    });
    document.querySelectorAll('.option').forEach(function (btn) {
      btn.addEventListener('click', function () {
        handleOption(btn.dataset.opt);
      });
    });
    setStep(1);
  });
})();
</script>
</body>
</html>
